const re = /\d+/g;                       // một hoặc nhiều chữ số, toàn cục
const text = "Phòng 12, tầng 7, năm 2026";

console.log(text.match(re));              // ["12","7","2026"]
console.log(/^\d{4}$/.test("2026"));      // true  (đúng 4 chữ số)
console.log("a  b   c".replace(/\s+/g, " "));   // "a b c"

// Nhóm bắt (capture group)
const m = "21/11/2026".match(/(\d+)\/(\d+)\/(\d+)/);
console.log(m[3], m[2], m[1]);            // 2026 11 21

